-- RAVA behavioral personalization foundation: authenticated product views.
alter table public.recommendation_engine_settings add column if not exists view_affinity_weight numeric not null default 5 check(view_affinity_weight between 0 and 1000);
create table if not exists public.customer_product_views(tenant_id uuid not null references public.tenants(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,view_count integer not null default 1 check(view_count>0),first_viewed_at timestamptz not null default now(),last_viewed_at timestamptz not null default now(),primary key(tenant_id,user_id,product_id));
create index if not exists customer_product_views_recent_idx on public.customer_product_views(tenant_id,user_id,last_viewed_at desc);alter table public.customer_product_views enable row level security;
drop policy if exists customer_product_views_self_select on public.customer_product_views;create policy customer_product_views_self_select on public.customer_product_views for select to authenticated using(user_id=auth.uid());
create or replace function public.record_customer_product_view(p_tenant uuid,p_product uuid) returns void language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();begin if u is null then return;end if;if not exists(select 1 from public.customer_profiles cp where cp.tenant_id=p_tenant and cp.user_id=u) then return;end if;if not exists(select 1 from public.products p where p.tenant_id=p_tenant and p.id=p_product and p.status='active') then return;end if;insert into public.customer_product_views(tenant_id,user_id,product_id,view_count,first_viewed_at,last_viewed_at) values(p_tenant,u,p_product,1,now(),now()) on conflict(tenant_id,user_id,product_id) do update set view_count=least(public.customer_product_views.view_count+1,1000000),last_viewed_at=now();end$$;
revoke all on function public.record_customer_product_view(uuid,uuid) from public;grant execute on function public.record_customer_product_view(uuid,uuid) to authenticated;
insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values('commerce.recommendations.behavior','یادگیری از بازدید محصول','RAVA برای مشتری واردشده از مشاهده محصولات هم سیگنال سلیقه می‌سازد. بازدیدهای تازه در مراحل بعدی شخصی‌سازی اثر بیشتری می‌گیرند.','داده بازدید فقط برای همان کاربر و همان Tenant استفاده شود.','Product-view learning','RAVA records signed-in product views as preference signals for personalization. Recent behavior can be weighted more heavily by later recommendation logic.','View data is scoped to the same signed-in user and tenant.',true) on conflict(help_key) do update set title_fa=excluded.title_fa,body_fa=excluded.body_fa,warning_fa=excluded.warning_fa,title_en=excluded.title_en,body_en=excluded.body_en,warning_en=excluded.warning_en,active=true;